<script setup lang="ts">import {reactive,ref} from 'vue';import {useRouter} from 'vue-router';import {ElMessage} from 'element-plus';import {useSession} from '../stores/session';const form=reactive({username:'admin',password:''}),loading=ref(false),router=useRouter(),session=useSession();async function submit(){loading.value=true;try{await session.login(form.username,form.password);router.push('/dashboard')}catch(e:any){ElMessage.error(e.message)}finally{loading.value=false}}</script>
<template><main class="login-page"><section class="login-brand"><b>鄞领π</b><h1>运营管理平台</h1><p>用户、活动、问卷、积分与兑换业务管理</p></section><el-form class="login-form" label-position="top" @submit.prevent="submit"><h2>管理员登录</h2><el-form-item label="账号"><el-input v-model="form.username"/></el-form-item><el-form-item label="密码"><el-input v-model="form.password" type="password" show-password @keyup.enter="submit"/></el-form-item><el-button type="primary" :loading="loading" @click="submit">登录</el-button></el-form></main></template>
